.minimal-brand .binary-byte>span{font:inherit!important;width:auto;height:auto;background:none;border:0;padding:0;color:var(--accent)}
.minimal-brand .quest-word{font:700 20px var(--sans,Inter,sans-serif);color:var(--text)}
.white-card,.leader-table-wrap,.leader-summary,.quest-strip,.profile-dropdown>button,.leader-tabs{box-shadow:inset 0 1px var(--glass-highlight),var(--glass-shadow);background-image:linear-gradient(145deg,var(--glass-highlight),transparent 45%)}
.white-card{border:1px solid var(--border)}
