button,a,input,select,textarea{ -webkit-tap-highlight-color:transparent }
button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,summary:focus-visible,svg[tabindex]:focus-visible{outline:2px solid var(--accent);outline-offset:3px}
.rank-number{display:inline-flex;align-items:center;gap:8px;white-space:nowrap}
