.rank-cup.gold{color:#ab770c}.rank-cup.silver{color:#687e97}.rank-cup.bronze{color:#a6622e}
[data-theme=dark] .rank-cup.gold{color:#f0cb62}[data-theme=dark] .rank-cup.silver{color:#c2d0df}[data-theme=dark] .rank-cup.bronze{color:#e4a16f}
