.code-scroll{position:relative}.editor-completions{position:absolute;z-index:9;min-width:210px;max-width:min(340px,90%);max-height:220px;overflow:auto;padding:5px;border:1px solid var(--border);border-radius:9px;background:var(--surface);box-shadow:0 10px 35px #0004;font:12px/1.5 var(--mono,monospace)}.editor-completions[hidden]{display:none}.editor-completions button{display:block;width:100%;text-align:left;padding:7px 10px;border:0;border-radius:5px;background:none;color:var(--text);font:inherit;cursor:pointer}.editor-completions button[aria-selected=true],.editor-completions button:hover{background:var(--blue-soft);color:var(--accent)}
.problem-table td small.problem-points{display:block;font-size:10px;color:var(--muted);margin:5px 0 0 8px}
