}
.community-page #profileContent .profile-title{
  display:flex;align-items:center;flex-wrap:wrap;
  gap:7px 10px;margin:2px 0 5px!important;
  font:650 clamp(22px,2.4vw,27px)/1.2 var(--font-sans)!important;
  letter-spacing:-.04em;color:var(--text);
}
.community-page #profileContent .profile-title .rank-name-text{
  max-width:100%;overflow-wrap:anywhere;
}
.community-page #profileContent .profile-title .rank-cup{
  width:23px;height:23px;flex-shrink:0;
}
.community-page #profileContent .profile-inline-rank{
  padding:4px 7px;
  font:500 10px/1.3 var(--font-sans);
  background:var(--surface-2);
  border:1px solid var(--border);
  border-radius:6px;
}
.community-page #profileContent .admin-badge{
  padding:4px 7px;
  background:var(--surface-2)!important;
  border:1px solid var(--border)!important;
