.community-page #profileContent .profile-linkedin,
.community-page #profileContent .user-profile-icon{
  width:22px;height:22px;min-width:22px;
  border-radius:6px;
}
.community-page #profileContent .profile-hero .profile-actions{
  display:flex;align-self:center;flex:0 0 auto;
  gap:8px;max-width:240px;
}
.community-page #profileContent .profile-actions .button{
  border:1px solid var(--border);background:var(--surface-2);
  border-radius:8px;padding:9px 13px;
  min-height:35px;
  color:var(--text);font:500 11px var(--font-sans);
