}
.community-page #profileContent .profile-actions .button:hover{border-color:var(--accent);color:var(--accent)}
.community-page #profileContent .profile-bio{
  padding:0 0 10px;margin:0;
  font:400 11px/1.7 var(--font-sans);
}
