/* The solved list reads like a compact table, with consistent columns. */
.community-page #profileContent .recent-solves{
  margin:0 0 20px;padding:0 0 20px;
  border-bottom:1px solid var(--border);
}
.community-page #profileContent .recent-solves>header{
  display:flex;align-items:center;gap:15px;
  margin:0 0 10px!important;
}
.community-page #profileContent .recent-solves h3{
  margin:0 0 5px!important;
  font:600 14px/1.45 var(--font-sans)!important;
  letter-spacing:-.015em;
}
.community-page #profileContent .recent-solves header p{
  font:400 10px/1.5 var(--font-sans)!important;
  color:var(--muted)!important;margin:0;
}
.community-page #profileContent .recent-toggle{
  margin-left:auto;
  padding:7px 10px!important;
  border:1px solid var(--border);
