.community-page #profileContent .recent-toggle:hover{border-color:var(--accent);color:var(--accent)}
.community-page #profileContent .recent-solves ol{list-style:none;margin:0;padding:0}
.community-page #profileContent .recent-solves li{
  border-bottom:1px solid var(--border);
}
.community-page #profileContent .recent-solves li:last-child{border-bottom:0}
.community-page #profileContent .recent-solves li a{
  display:grid;align-items:center;
  grid-template-columns:42px minmax(0,1fr) 75px 108px;
