}
.community-page #profileContent .recent-difficulty{
  justify-self:start;font:500 10px/1.3 var(--font-sans);
}
.community-page #profileContent .recent-solves time{
  justify-self:end;text-align:right;
  font:400 10px/1.5 var(--font-mono);
  color:var(--muted);white-space:nowrap;
