/* Minimal profile editor: native dialog keeps focus and keyboard semantics. */
.profile-edit-dialog{
  box-sizing:border-box;width:min(720px,calc(100vw - 32px));
  max-height:min(88dvh,850px);margin:auto;padding:0;
  overflow:auto;overscroll-behavior:contain;
  color:var(--text);background:var(--surface)!important;
  border:1px solid var(--border)!important;border-radius:16px;
  box-shadow:0 24px 90px #0007!important;
}
.profile-edit-dialog::backdrop{
  background:rgba(0,0,0,.67);backdrop-filter:blur(3px);
}
.profile-edit-dialog #editPanel.white-card{
  display:block!important;min-height:0;
  width:100%;max-width:none!important;margin:0!important;
  padding:0!important;border:0!important;border-radius:0!important;
  background:var(--surface)!important;box-shadow:none!important;
}
.profile-edit-dialog .profile-edit-header{
  display:flex;justify-content:space-between;align-items:flex-start;gap:12px;
  padding:25px 29px 15px;
}
.profile-edit-dialog .profile-edit-header .eyebrow{
  font:550 9px/1.5 var(--font-sans);
  letter-spacing:.08em;color:var(--accent);
}
.profile-edit-dialog .profile-edit-header h2{
  margin:4px 0!important;font:650 24px/1.3 var(--font-sans)!important;
