  font:400 10px/1.5 var(--font-sans);color:var(--muted);
}
.profile-edit-dialog .profile-edit-count{align-self:flex-end}
.profile-edit-dialog .photo-preview{
  width:44px!important;height:44px!important;border-radius:10px;object-fit:cover;
}
.profile-edit-dialog .profile-edit-optional{
  border-top:1px solid var(--border);padding:15px 0;
}
.profile-edit-dialog .profile-edit-optional summary,
.profile-edit-dialog .profile-edit-danger summary{
  display:flex;gap:8px;align-items:center;cursor:pointer;
  font:550 12px/1.5 var(--font-sans);color:var(--text);
}
.profile-edit-dialog .profile-edit-optional summary small{
  color:var(--muted);font-size:10px;
}
.profile-edit-dialog .profile-details-fields{
  margin-top:15px!important;border:0!important;
  padding:0!important;min-width:0;
}
.profile-edit-dialog .profile-details-fields legend{display:none}
.profile-edit-dialog .profile-edit-privacy .checkbox-label{
  display:flex!important;flex-direction:row!important;
  align-items:flex-start;gap:10px;
  color:var(--text);line-height:1.5;
  cursor:pointer;
}
.profile-edit-dialog .checkbox-label input{
  width:15px!important;height:15px!important;min-width:15px;margin-top:1px;
