}
.profile-edit-dialog .profile-edit-status[hidden]{display:none!important}
.profile-edit-dialog .profile-edit-status[data-error=true]{color:var(--danger)}
.profile-edit-dialog .profile-edit-actions{
  position:sticky;bottom:0;z-index:2;
  display:flex;justify-content:flex-end;gap:9px;
  background:var(--surface);border-top:1px solid var(--border);
  padding:14px 0;margin:14px 0 0;
}
.profile-edit-dialog .profile-edit-actions .button{
  min-width:100px;min-height:37px;border-radius:8px;
  font:550 11px var(--font-sans);
}
.profile-edit-dialog .profile-edit-actions button:disabled{opacity:.65;cursor:wait}
.profile-edit-dialog .profile-edit-danger{
  padding:13px 29px 20px;margin:0!important;
  border-top:1px solid var(--border);
}
.profile-edit-dialog .profile-edit-danger h3{font-size:12px}
.profile-edit-dialog .profile-edit-danger p{font-size:10px;color:var(--muted)}
@media(max-width:610px){
  .profile-edit-dialog{width:calc(100vw - 18px);max-height:94dvh;border-radius:12px}
  .profile-edit-dialog .profile-edit-header{padding:19px 17px 13px}
  .profile-edit-dialog .profile-edit-preview{margin:0 17px 13px}
  .profile-edit-dialog .profile-form{padding:0 17px 4px}
  .profile-edit-dialog .profile-edit-danger{padding:13px 17px 18px}
}
@media(prefers-reduced-motion:reduce){
  .profile-edit-dialog::backdrop{backdrop-filter:none}
