import {escapeHtml as h} from './community-model.js';
import {relativeTime} from './presence-model.js?v=social-1';
const symbols={solved:'<path d="m6 12 4 4 8-8"/><circle cx="12" cy="12" r="9"/>',points:'<path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9L12 3Z"/>',streak:'<path d="M12 3c1 5-4 5-4 9 0 2 1 3 2 3-1-3 2-4 3-6 4 3 6 6 4 9a6 6 0 0 1-10-1C3 11 9 9 12 3Z"/>'};
const icon=kind=>'<span class="metric-icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">'+symbols[kind]+'</svg></span>';
export function profileMetrics(stats,points,total){
 const solved=Number(stats.solved)||0,streak=Number(stats.streak)||0,count=Number(stats.total??total)||0,progress=count?Math.max(0,Math.min(100,solved/count*100)):0;
 return '<div class="social-stats profile-metrics"><section class="social-stat metric-solved">'+icon('solved')+'<span class="metric-label">Problems solved</span><b id="profileSolvedCount">'+solved+'<small> / '+count+'</small></b><span class="metric-caption">Published challenges</span><span class="metric-progress" aria-hidden="true"><i style="width:'+progress+'%"></i></span></section><section class="social-stat metric-points">'+icon('points')+'<span class="metric-label">Total points</span><b>'+Number(points||0).toLocaleString()+'</b><span class="metric-caption">Your problem-solving score</span></section><section class="social-stat metric-streak">'+icon('streak')+'<span class="metric-label">Daily streak</span><b class="streak-count'+(streak>0?' is-burning':'')+'">'+'<span class="streak-digits">'+streak+'</span><small> '+(streak===1?'day':'days')+'</small></b><span class="metric-caption">'+(stats.streakAdjusted?'Administratively adjusted streak':'Consecutive solve days')+'</span><div class="streak-reset" aria-label="Countdown to the next UTC streak day"><span>New day in</span><time data-streak-countdown role="timer" aria-live="off" title="UTC midnight · streaks reset daily at 00:00 UTC">--:--:--</time><small>UTC</small></div></section></div>';
}
// Problem numbers follow the current published catalog order, exactly as
// they do in the problem library. Missing metadata is never guessed.
export function profileCatalogNumbers(catalog=[]){
 const nums=new Map();
 if(!Array.isArray(catalog))return nums;
 catalog.forEach((problem,index)=>{
  if(typeof problem?.id==='string'&&!nums.has(problem.id))nums.set(problem.id,index+1);
 });
 return nums;
}
export function hydrateRecentProblemNumbers(container,catalog=[]){
 if(!container?.querySelectorAll)return;
 const nums=profileCatalogNumbers(catalog);
 container.querySelectorAll('[data-recent-problem-number]').forEach(node=>{
  const number=nums.get(node.getAttribute('data-recent-problem-number'));
  node.textContent=number?String(number).padStart(2,'0'):'—';
  node.setAttribute('aria-label',number?'Problem '+number:'Problem number unavailable');
 });
}
export function recentSolvesMarkup(items=[],catalog=[]){
 const rows=items.slice(0,25),numbers=profileCatalogNumbers(catalog);
 return '<section class="recent-solves"><header><div><h3>Recently solved</h3><p>Latest accepted solves · up to 25 problems</p></div>'+
  (rows.length>3?'<button type="button" class="recent-toggle" aria-expanded="false" aria-controls="recentSolvesList" data-recent-toggle>Show all '+rows.length+' <span aria-hidden="true">↗</span></button>':'')+
  '</header>'+(rows.length?'<ol id="recentSolvesList">'+rows.map((s,i)=>{
   const number=numbers.get(s.problemId),label=number?String(number).padStart(2,'0'):'—';
   return '<li '+(i>=3?'hidden ':'')+'data-recent-row><a href="./index.html?problem='+encodeURIComponent(s.problemId)+'#practice">'+
    '<span class="recent-problem-number" data-recent-problem-number="'+h(s.problemId)+'" aria-label="'+(number?'Problem '+number:'Problem number unavailable')+'">'+label+'</span>'+
    '<span class="recent-problem-title">'+h(s.title)+'</span>'+
    '<span class="recent-difficulty '+h(String(s.difficulty).toLowerCase())+'">'+h(s.difficulty)+'</span>'+
    '<time datetime="'+h(s.solvedAt)+'" title="'+h(s.solvedAt)+'">'+h(relativeTime(s.solvedAt)||'Solved')+'</time></a></li>';
  }).join('')+'</ol>':'<p class="recent-empty">Solved problems will appear here.</p>')+'</section>';
}

export const languageNames={java:'Java',python:'Python',c:'C',cpp:'C++'};
function https(value,label){if(typeof value!=='string'||value.length>1000)throw new Error(label+' must be an HTTPS link under 1,000 characters.');const raw=value.trim();if(!raw)return '';let u;try{u=new URL(raw);}catch{}if(!u||u.protocol!=='https:'||u.username||u.password||/[\u0000-\u001f]/.test(raw))throw new Error(label+' must be a valid HTTPS link.');return u.href;}
export function profileDetails(body){
 const keys=['organization_type','organization_name','organization_url','linkedin_url','github_url'];if(!keys.some(k=>Object.hasOwn(body,k)))return{};
 for(const k of keys)if(typeof (body[k]??'')!=='string')throw new Error('Check your optional profile details.');
 let type=(body.organization_type||'').trim(),name=(body.organization_name||'').trim();if(!['','company','organization','university'].includes(type)||name.length>100)throw new Error('Choose an organization type and a name under 100 characters.');
 const url=name?https(body.organization_url||'','Organization website'):'';if(!name)type='';else if(!type)type='organization';
 let linkedin=https(body.linkedin_url||'','LinkedIn profile');if(linkedin){const u=new URL(linkedin);if(!['linkedin.com','www.linkedin.com'].includes(u.hostname.toLowerCase())||u.port||!/^\/in\/[a-zA-Z0-9%_.~-]+\/?$/.test(u.pathname))throw new Error('Use a LinkedIn profile link such as https://www.linkedin.com/in/your-name/.');u.search='';u.hash='';linkedin=u.href;}
 let github=https(body.github_url||'','GitHub profile');
 if(github){const u=new URL(github);if(!['github.com','www.github.com'].includes(u.hostname.toLowerCase())||u.port||!/^\/[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,37}[a-zA-Z0-9])?\/?$/.test(u.pathname))throw new Error('Use a GitHub profile link such as https://github.com/your-username.');u.hostname='github.com';u.search='';u.hash='';github=u.href;}
 return{organization_type:type,organization_name:name,organization_url:url,linkedin_url:linkedin,github_url:github};
}

/* ByteQuest profile design language: consistent right-aligned numbers,
   narrow expressive surfaces, and a year-at-a-glance grid. Source of truth
   remains the server's accepted solves/streaks; this is presentation only. */

/* The same right boundary and typographic rhythm in every metric column. */
.community-page #profileContent .profile-overview{
  grid-template-columns:minmax(0,385px) minmax(0,1fr)!important;
  gap:clamp(12px,2vw,30px)!important;
}
.community-page #profileContent .profile-overview .social-stats.profile-metrics{
  display:grid!important;
  grid-template-columns:repeat(3,minmax(0,1fr))!important;
  align-items:start!important;
  justify-items:stretch!important;
  gap:4px clamp(8px,1.55vw,26px)!important;
  margin:0!important;
  padding:0!important;
  border:0!important;
  background:transparent!important;
}
.community-page #profileContent .profile-overview .profile-metrics .social-stat{
  display:grid!important;
  grid-template-columns:minmax(0,1fr)!important;
  grid-template-rows:18px 62px minmax(32px,auto)!important;
  justify-items:end!important;
  align-items:start!important;
  row-gap:5px!important;
  min-width:0!important;
  min-height:0!important;
  margin:0!important;
  padding:0!important;
  border:0!important;
  background:transparent!important;
  box-shadow:none!important;
  text-align:right!important;
}
.community-page #profileContent .profile-overview .profile-metrics .metric-label{
  display:block!important;
  grid-row:1;
  width:100%;
  padding:0!important;
  margin:0!important;
  text-align:right!important;
  font:500 11px/18px var(--font-sans)!important;
  color:var(--muted)!important;
  white-space:normal!important;
}
.community-page #profileContent .profile-overview .profile-metrics .social-stat b{
  display:flex!important;
  grid-row:2;
  align-self:start!important;
  align-items:baseline!important;
  justify-content:flex-end!important;
  width:100%;
  height:62px!important;
  min-height:62px!important;
  margin:0!important;
  padding:0!important;
  gap:3px!important;
  font:600 clamp(36px,3.4vw,52px)/1.04 var(--font-sans)!important;
  font-variant-numeric:tabular-nums lining-nums!important;
  font-feature-settings:"tnum" 1,"lnum" 1;
  letter-spacing:-.05em!important;
  text-align:right!important;
  color:var(--text)!important;
  white-space:nowrap!important;
}
.community-page #profileContent .profile-overview .profile-metrics .metric-solved b{
  color:var(--accent)!important;
}
.community-page #profileContent .profile-overview .profile-metrics .social-stat b small{
  display:inline-block!important;
  flex:0 0 auto!important;
  align-self:baseline!important;
  font:400 clamp(11px,.95vw,14px)/1.4 var(--font-sans)!important;
  letter-spacing:0!important;
  color:var(--muted)!important;
  white-space:nowrap!important;
}
.community-page #profileContent .profile-overview .profile-metrics .streak-count{
  justify-content:flex-end!important;
  align-items:baseline!important;
}
.community-page #profileContent .profile-overview .profile-metrics .streak-count .streak-digits{
  font:inherit!important;
  font-variant-numeric:tabular-nums lining-nums!important;
}
.community-page #profileContent .profile-overview .profile-metrics .streak-flame{display:none!important}
.community-page #profileContent .profile-overview .profile-metrics .metric-caption{
  display:block!important;
  grid-row:3;
  justify-self:end!important;
  align-self:start!important;
  width:100%;
  max-width:18ch!important;
  min-height:28px;
  margin:0!important;
  text-align:right!important;
  font:400 11px/1.45 var(--font-sans)!important;
  color:var(--muted)!important;
}
.community-page #profileContent .profile-overview .profile-metrics .streak-milestones{
  grid-column:1/-1!important;
